where li.product_id = p.id
  and p.sku = $maeander$WHG-R-1808$maeander$
  and li.url like $maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/%$maeander$;

select p.org_id, p.id, i.url, 'url', i.alt, i.position
from public.products p
join public.organizations o on o.id = p.org_id and o.name = 'EON'
cross join (values
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/01-hero.jpg$maeander$, $maeander$18k white gold Greek key wedding band on geometric glass, three-quarter view$maeander$, 0),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/02-macro.jpg$maeander$, $maeander$Macro detail of the Maeander pattern, milgrain and rope rails in 18k white gold$maeander$, 1),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/03-side.jpg$maeander$, $maeander$Side view of the 18k white gold Greek key band and polished comfort-fit interior$maeander$, 2),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/04-top.jpg$maeander$, $maeander$Top view of the solid 18k white gold Maeander wedding band$maeander$, 3),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/05-on-hand.jpg$maeander$, $maeander$18k white gold Greek key wedding band worn on an adult hand$maeander$, 4),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/06-editorial.jpg$maeander$, $maeander$EON Maeander 18k white gold ring in Aegean Glass light and natural shadow$maeander$, 5),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/07-size-width-guide.jpg$maeander$, $maeander$Ring size and width guide for US 4 to 16 and 3mm to 12mm$maeander$, 6),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/08-metal-karat-guide.jpg$maeander$, $maeander$18K White Gold material and color guide$maeander$, 7),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/09-personalization-care.jpg$maeander$, $maeander$Inside engraving and solid gold ring care guide$maeander$, 8),
  ($maeander$https://amuletta.artifactstudio.info/eon/maeander-1008/whg-r-1808/10-made-to-order.jpg$maeander$, $maeander$Made-to-order processing and shipping expectations$maeander$, 9)
) as i(url, alt, position)
where p.sku = $maeander$WHG-R-1808$maeander$;

